      out.write("    <script>\r\n");
      out.write("        // Page loader\r\n");
      out.write("        window.addEventListener('load', function() {\r\n");
      out.write("            setTimeout(() => {\r\n");
      out.write("                document.getElementById('pageLoader').classList.add('hidden');\r\n");
      out.write("            }, 1500);\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Navbar scroll effect\r\n");
      out.write("        window.addEventListener('scroll', function() {\r\n");
      out.write("            const navbar = document.getElementById('navbar');\r\n");
      out.write("            if (window.scrollY > 100) {\r\n");
      out.write("                navbar.classList.add('scrolled');\r\n");
      out.write("            } else {\r\n");
      out.write("                navbar.classList.remove('scrolled');\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Mobile menu toggle\r\n");
      out.write("        document.getElementById('mobileMenuBtn').addEventListener('click', function() {\r\n");
      out.write("            const navMenu = document.getElementById('navMenu');\r\n");
      out.write("            navMenu.classList.toggle('active');\r\n");
      out.write("            this.innerHTML = navMenu.classList.contains('active') ? '&#10005;' : '&#9776;';\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Close mobile menu when clicking on a link\r\n");
      out.write("        document.querySelectorAll('.nav-link').forEach(link => {\r\n");
      out.write("            link.addEventListener('click', function() {\r\n");
      out.write("                const navMenu = document.getElementById('navMenu');\r\n");
      out.write("                const mobileMenuBtn = document.getElementById('mobileMenuBtn');\r\n");
      out.write("                navMenu.classList.remove('active');\r\n");
      out.write("                mobileMenuBtn.innerHTML = '&#9776;';\r\n");
      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Smooth scrolling for navigation links\r\n");
      out.write("        document.querySelectorAll('a[href^=\"#\"]').forEach(anchor => {\r\n");
      out.write("            anchor.addEventListener('click', function (e) {\r\n");
      out.write("                e.preventDefault();\r\n");
      out.write("                const target = document.querySelector(this.getAttribute('href'));\r\n");
      out.write("                if (target) {\r\n");
      out.write("                    target.scrollIntoView({\r\n");
      out.write("                        behavior: 'smooth',\r\n");
      out.write("                        block: 'start'\r\n");
      out.write("                    });\r\n");
      out.write("                }\r\n");
      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Enhanced button interactions with ripple effect\r\n");
      out.write("        document.addEventListener('DOMContentLoaded', function() {\r\n");
      out.write("            const buttons = document.querySelectorAll('.btn, .quantity-btn');\r\n");
      out.write("            buttons.forEach(button => {\r\n");
      out.write("                button.addEventListener('click', function(e) {\r\n");
      out.write("                    const ripple = document.createElement('span');\r\n");
      out.write("                    const rect = this.getBoundingClientRect();\r\n");
      out.write("                    const size = Math.max(rect.width, rect.height);\r\n");
      out.write("                    const x = e.clientX - rect.left - size / 2;\r\n");
      out.write("                    const y = e.clientY - rect.top - size / 2;\r\n");
      out.write("                    \r\n");
      out.write("                    ripple.style.cssText = `\r\n");
      out.write("                        position: absolute;\r\n");
      out.write("                        width: ${size}px;\r\n");
      out.write("                        height: ${size}px;\r\n");
      out.write("                        left: ${x}px;\r\n");
      out.write("                        top: ${y}px;\r\n");
      out.write("                        background: rgba(255, 255, 255, 0.3);\r\n");
      out.write("                        border-radius: 50%;\r\n");
      out.write("                        transform: scale(0);\r\n");
      out.write("                        animation: ripple 0.6s linear;\r\n");
      out.write("                        pointer-events: none;\r\n");
      out.write("                        z-index: 10;\r\n");
      out.write("                    `;\r\n");
      out.write("                    \r\n");
      out.write("                    this.appendChild(ripple);\r\n");
      out.write("                    \r\n");
      out.write("                    setTimeout(() => {\r\n");
      out.write("                        ripple.remove();\r\n");
      out.write("                    }, 600);\r\n");
      out.write("                });\r\n");
      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Intersection Observer for animations\r\n");
      out.write("        const observerOptions = {\r\n");
      out.write("            threshold: 0.1,\r\n");
      out.write("            rootMargin: '0px 0px -50px 0px'\r\n");
      out.write("        };\r\n");
      out.write("\r\n");
      out.write("        const observer = new IntersectionObserver(function(entries) {\r\n");
      out.write("            entries.forEach(entry => {\r\n");
      out.write("                if (entry.isIntersecting) {\r\n");
      out.write("                    entry.target.style.opacity = '1';\r\n");
      out.write("                    entry.target.style.transform = 'translateY(0)';\r\n");
      out.write("                }\r\n");
      out.write("            });\r\n");
      out.write("        }, observerOptions);\r\n");
      out.write("\r\n");
      out.write("        document.querySelectorAll('.cart-item, .cart-summary').forEach(el => {\r\n");
      out.write("            el.style.opacity = '0';\r\n");
      out.write("            el.style.transform = 'translateY(30px)';\r\n");
      out.write("            el.style.transition = 'all 0.6s ease-out';\r\n");
      out.write("            observer.observe(el);\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Add ripple animation keyframes\r\n");
      out.write("        const style = document.createElement('style');\r\n");
      out.write("        style.textContent = `\r\n");
      out.write("            @keyframes ripple {\r\n");
      out.write("                to {\r\n");
      out.write("                    transform: scale(4);\r\n");
      out.write("                    opacity: 0;\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("        `;\r\n");
      out.write("        document.head.appendChild(style);\r\n");
      out.write("\r\n");
      out.write("        // Cart functionality\r\n");
      out.write("        function updateQuantity(productId, change) {\r\n");
      out.write("            const input = document.querySelector(`input[onchange=\"updateQuantityInput(${productId}, this)\"]`);\r\n");
      out.write("            const newValue = parseInt(input.value) + change;\r\n");
      out.write("            const max = parseInt(input.max);\r\n");
      out.write("            \r\n");
      out.write("            if (newValue >= 1 && newValue <= max) {\r\n");
      out.write("                input.value = newValue;\r\n");
      out.write("                sendQuantityUpdate(productId, newValue);\r\n");
      out.write("            } else if (newValue < 1) {\r\n");
      out.write("                input.value = 1;\r\n");
      out.write("            } else if (newValue > max) {\r\n");
      out.write("                input.value = max;\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        function updateQuantityInput(productId, input) {\r\n");
      out.write("            let value = parseInt(input.value);\r\n");
      out.write("            const max = parseInt(input.max);\r\n");
      out.write("            \r\n");
      out.write("            if (isNaN(value) || value < 1) {\r\n");
      out.write("                value = 1;\r\n");
      out.write("            } else if (value > max) {\r\n");
      out.write("                value = max;\r\n");
      out.write("            }\r\n");
      out.write("            \r\n");
      out.write("            input.value = value;\r\n");
      out.write("            sendQuantityUpdate(productId, value);\r\n");
      out.write("        }\r\n");
      out.write("        \r\n");
      out.write("        function sendQuantityUpdate(productId, quantity) {\r\n");
      out.write("            fetch('updateCart?productId=' + productId + '&quantity=' + quantity, {\r\n");
      out.write("                method: 'POST',\r\n");
      out.write("                credentials: 'include'\r\n");
      out.write("            })\r\n");
      out.write("            .then(response => {\r\n");
      out.write("                if (!response.ok) {\r\n");
      out.write("                    throw new Error('Network response was not ok: ' + response.statusText);\r\n");
      out.write("                }\r\n");
      out.write("                return response.json();\r\n");
      out.write("            })\r\n");
      out.write("            .then(data => {\r\n");
      out.write("                if (data.success) {\r\n");
      out.write("                    // Update cart count in nav-menu\r\n");
      out.write("                    const cartCountElements = document.querySelectorAll('.nav-menu .nav-link[href=\"cart.jsp\"]');\r\n");
      out.write("                    cartCountElements.forEach(el => {\r\n");
      out.write("                        el.innerHTML = `&#128722; Cart (${data.cartCount})`;\r\n");
      out.write("                    });\r\n");
      out.write("\r\n");
      out.write("                    // Update cart summary\r\n");
      out.write("                    const totalItems = document.querySelector('.total-items');\r\n");
      out.write("                    const subtotalElement = document.querySelector('.subtotal');\r\n");
      out.write("                    const taxElement = document.querySelector('.tax');\r\n");
      out.write("                    const totalElement = document.querySelector('.total');\r\n");
      out.write("                    const checkoutButton = document.querySelector('#checkoutForm button[type=\"submit\"]');\r\n");
      out.write("                    let newSubtotal = 0;\r\n");
      out.write("                    let newItemCount = 0;\r\n");
      out.write("\r\n");
      out.write("                    // Update cart items and calculate new subtotal and item count\r\n");
      out.write("                    if (data.items && Array.isArray(data.items)) {\r\n");
      out.write("                        data.items.forEach(item => {\r\n");
      out.write("                            newSubtotal += item.price * item.quantity;\r\n");
      out.write("                            newItemCount += item.quantity;\r\n");
      out.write("\r\n");
      out.write("                            // Update individual cart item\r\n");
      out.write("                            const cartItem = document.querySelector(`.cart-item[data-product-id=\"${item.productId}\"]`);\r\n");
      out.write("                            if (cartItem) {\r\n");
      out.write("                                const stockElement = cartItem.querySelector('.stock-quantity');\r\n");
      out.write("                                const outOfStockElement = cartItem.querySelector('.out-of-stock');\r\n");
      out.write("                                const minusBtn = cartItem.querySelector('.quantity-btn.minus');\r\n");
      out.write("                                const plusBtn = cartItem.querySelector('.quantity-btn.plus');\r\n");
      out.write("                                const quantityInput = cartItem.querySelector('.quantity-input');\r\n");
      out.write("\r\n");
      out.write("                                quantityInput.value = item.quantity;\r\n");
      out.write("                                quantityInput.max = item.stockQuantity;\r\n");
      out.write("\r\n");
      out.write("                                if (item.quantity > item.stockQuantity) {\r\n");
      out.write("                                    if (outOfStockElement) {\r\n");
      out.write("                                        outOfStockElement.textContent = `Only ${item.stockQuantity} available (you have ${item.quantity})`;\r\n");
      out.write("                                    } else {\r\n");
      out.write("                                        const newOutOfStock = document.createElement('p');\r\n");
      out.write("                                        newOutOfStock.className = 'out-of-stock';\r\n");
      out.write("                                        newOutOfStock.textContent = `Only ${item.stockQuantity} available (you have ${item.quantity})`;\r\n");
      out.write("                                        cartItem.querySelector('.cart-item-price').insertAdjacentElement('afterend', newOutOfStock);\r\n");
      out.write("                                    }\r\n");
      out.write("                                } else {\r\n");
      out.write("                                    if (outOfStockElement) outOfStockElement.remove();\r\n");
      out.write("                                    if (stockElement) stockElement.textContent = item.stockQuantity;\r\n");
      out.write("                                }\r\n");
      out.write("\r\n");
      out.write("                                minusBtn.disabled = item.quantity <= 1;\r\n");
      out.write("                                plusBtn.disabled = item.quantity >= item.stockQuantity;\r\n");
      out.write("                            }\r\n");
      out.write("                        });\r\n");
      out.write("\r\n");
      out.write("                        // Update Order Summary\r\n");
      out.write("                        totalItems.textContent = newItemCount;\r\n");
      out.write("                        subtotalElement.textContent = `$${newSubtotal.toFixed(2)}`;\r\n");
      out.write("                        taxElement.textContent = `$${(newSubtotal * 0.1).toFixed(2)}`;\r\n");
      out.write("                        totalElement.textContent = `$${(newSubtotal * 1.1).toFixed(2)}`;\r\n");
      out.write("\r\n");
      out.write("                        // Update checkout button state\r\n");
      out.write("                        const hasStockIssues = data.items.some(i => i.quantity > i.stockQuantity);\r\n");
      out.write("                        checkoutButton.disabled = hasStockIssues;\r\n");
      out.write("                        checkoutButton.textContent = hasStockIssues ? 'Adjust quantities to checkout' : 'Proceed to Checkout';\r\n");
      out.write("\r\n");
      out.write("                        // Show success message\r\n");
      out.write("                        const successDiv = document.createElement('div');\r\n");
      out.write("                        successDiv.className = 'alert alert-success';\r\n");
      out.write("                        successDiv.textContent = 'Cart updated successfully!';\r\n");
      out.write("                        document.querySelector('.cart-title').insertAdjacentElement('afterend', successDiv);\r\n");
      out.write("                        setTimeout(() => successDiv.remove(), 2000);\r\n");
      out.write("                    } else {\r\n");
      out.write("                        throw new Error('Invalid items data in response');\r\n");
      out.write("                    }\r\n");
      out.write("                } else {\r\n");
      out.write("                    const errorDiv = document.createElement('div');\r\n");
      out.write("                    errorDiv.className = 'alert alert-error';\r\n");
      out.write("                    errorDiv.textContent = data.message || 'Failed to update quantity.';\r\n");
      out.write("                    document.querySelector('.cart-title').insertAdjacentElement('afterend', errorDiv);\r\n");
      out.write("                    setTimeout(() => errorDiv.remove(), 3000);\r\n");
      out.write("                }\r\n");
      out.write("            })\r\n");
      out.write("            .catch(err => {\r\n");
      out.write("                console.error('Update quantity error:', err);\r\n");
